// Anomaly defines model for Anomaly.
type Anomaly struct {
	// Code z. B. P1, P2, P3 (ODO-03), F1 (FU-08), OIL_CAPACITY (OI-05)
	Code        string                                `json:"code"`
	Confirmable bool                                  `json:"confirmable"`
	Message     *string                               `json:"message,omitempty"`
	RelatedId   nullable.Nullable[openapi_types.UUID] `json:"related_id,omitempty"`
}

